mapper.update:
UPDATE team_employees
SET is_leader = #{isLeader},
    updated_at = CURRENT_TIMESTAMP
WHERE team_code = #{teamCode}
  AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}


DELETE FROM team_employees
WHERE team_code = #{teamCode}
  AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value};


UPDATE team_employees
SET delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value},
    deleted_at = CURRENT_TIMESTAMP
WHERE team_code = #{teamCode}
  AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

UPDATE team_employees
SET delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value},
    deleted_at = NULL,
    role_code = #{roleCode},
    is_leader = #{isLeader},
    updated_at = CURRENT_TIMESTAMP
WHERE team_code = #{teamCode}
  AND employee_id = #{employeeId}
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@DELETED.value}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM team_employees
    WHERE team_code = #{teamCode}
      AND employee_id = #{employeeId}
      AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)

SELECT EXISTS(
    SELECT 1
    FROM team_employees
    WHERE team_code = #{teamCode}
      AND is_leader = true
      AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)

SELECT COUNT(*)
FROM team_employees
WHERE team_code = #{teamCode}
  AND is_leader = true
  AND delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT te.id as te_id,
       te.team_code,
       t.department_code,
       te.employee_id,
       te.role_code,
       te.is_leader,
       e.user_id,
       e.first_name,
       e.last_name,
       e.image_url
FROM team_employees te
INNER JOIN employees e ON te.employee_id = e.client_id
INNER JOIN teams t ON te.team_code = t.team_code
WHERE te.team_code = #{request.teamCode}
  AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND e.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND t.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

    AND e.user_id ILIKE '%' || #{request.userId} || '%'


    AND e.first_name ILIKE '%' || #{request.firstName} || '%'


    AND e.last_name ILIKE '%' || #{request.lastName} || '%'


    AND te.role_code = #{request.roleCode}


    ORDER BY e.${request.sortBy} ${request.sortOrder}


    LIMIT #{request.size} OFFSET #{request.offset}

SELECT COUNT(*)
FROM employees e
INNER JOIN team_employees te ON e.client_id = te.employee_id
WHERE te.team_code = #{request.teamCode}
  AND te.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND e.delete_flag = ${@com.uit.sociuscoremodules.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

    AND e.user_id ILIKE '%' || #{request.userId} || '%'


    AND e.first_name ILIKE '%' || #{request.firstName} || '%'


    AND e.last_name ILIKE '%' || #{request.lastName} || '%'


    AND te.role_code = #{request.roleCode}
